def workspaces_list(api_key, status=None, name_contains=None, limit=None, cursor=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0548000" if __import__("os").path.isdir("./environment_mix/0548000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, base64, hashlib

    t0 = time.time()
    now_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _rows(obj):
        if isinstance(obj, list): return obj
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list): return obj["rows"]
        return []

    ws_store = _load("workspaces.json")
    key_store = _load("api_keys.json")
    req_store = _load("request_logs.json")

    workspaces = _rows(ws_store)
    api_keys = _rows(key_store)
    request_logs = _rows(req_store)

    def _save_back(fname, original, rows):
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(fname, original)
        else:
            _save(fname, rows)

    def _log(status_code, api_key_id=None, api_key_prefix=None, workspace_id=None, message=None):
        entry = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{os.getpid()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": "workspaces-list",
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_code,
            "api_key_id": api_key_id,
            "api_key_prefix": api_key_prefix,
            "workspace_id": workspace_id,
            "message": message,
        }
        request_logs.append(entry)

    # ---- validate ----
    if not isinstance(api_key, str) or not api_key.strip():
        _log("VALIDATION_ERROR", message="api_key must be a non-empty string")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None and status not in ("active", "suspended", "deleted"):
        _log("VALIDATION_ERROR", message="Invalid status")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid status", allowed=["active", "suspended", "deleted"])
    if name_contains is not None and not isinstance(name_contains, str):
        _log("VALIDATION_ERROR", message="name_contains must be a string")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "name_contains must be a string")
    if limit is None:
        limit = 50
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", message="limit must be 1..200")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", message="cursor must be a string")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # ---- authenticate by matching provided value to api_keys.id OR api_keys.key_prefix (per contract) ----
    cred = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            cred = k
            break
    if cred is None:
        _log("UNAUTHORIZED", message="API key missing or invalid")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key missing or invalid")
    if cred.get("status") != "active":
        _log("UNAUTHORIZED", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=cred.get("workspace_id"), message="API key revoked")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked")

    # Least-privilege: only list caller's workspace
    caller_ws_id = cred.get("workspace_id")
    rows = [w for w in workspaces if isinstance(w, dict) and w.get("id") == caller_ws_id]

    # filters
    if status is not None:
        rows = [w for w in rows if w.get("status") == status]
    if name_contains is not None:
        needle = name_contains.lower()
        rows = [w for w in rows if isinstance(w.get("name"), str) and needle in w["name"].lower()]

    # sort stable by created_at then id
    def _sort_key(w):
        return (w.get("created_at") or "", w.get("id") or "")
    rows.sort(key=_sort_key)

    # pagination: cursor = base64("offset:<n>")
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8", "replace")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    offset = 0
        except Exception:
            offset = 0

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    _log("OK", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=caller_ws_id, message="listed")
    _save("request_logs.json", request_logs)
    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def workspaces_get(api_key, id, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0548000" if __import__("os").path.isdir("./environment_mix/0548000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    t0 = time.time()
    endpoint = "workspaces-get"

    # ---- validate input types
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    sessions = _load("execution_sessions.json")  # not used, but kept for consistency
    executions = _load("command_executions.json")  # not used, but kept for consistency
    counters = _load("usage_counters.json")

    # ---- authenticate: match by id OR key_prefix OR key_hash (client-visible in this store)
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break

    # prepare request log via usage_counters as observable dynamics (window_type="minute")
    # (schema does not define request_logs; we log calls as counters with exec_count as total calls)
    def _minute_start(dt):
        dt = dt.replace(second=0, microsecond=0)
        return dt

    def _find_or_create_counter(workspace_id, api_key_id, window_type, window_start_iso):
        for r in counters:
            if (
                r.get("workspace_id") == workspace_id
                and r.get("api_key_id") == api_key_id
                and r.get("window_type") == window_type
                and r.get("window_start") == window_start_iso
            ):
                return r
        cid = f"uc_{int(time.time()*1000)}_{len(counters)+1}"
        row = {
            "id": cid,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "window_type": window_type,
            "window_start": window_start_iso,
            "exec_count": 0,
            "rejected_count": 0,
            "timed_out_count": 0,
            "created_at": _now(),
            "updated_at": _now(),
        }
        counters.append(row)
        return row

    # If unauthenticated, we cannot attribute to a workspace; we still cannot create a counter row due to FK.
    # So we log only when we can resolve a workspace context.
    def _persist_auth_last_used(krow):
        krow["last_used_at"] = _now()
        krow["updated_at"] = _now()

    status_code = "UNAUTHORIZED"
    result = None

    if not key_row or key_row.get("status") != "active":
        # No valid key: return UNAUTHORIZED (cannot "log" without workspace_id FK)
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    ws = None
    for w in workspaces:
        if w.get("id") == key_row.get("workspace_id"):
            ws = w
            break
    if not ws:
        return _err("UNAUTHORIZED", "API key is not associated with a valid workspace")

    # Log this call in counters (workspace aggregate minute window) as "exec_count" = total calls
    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    mstart = _minute_start(now_dt).isoformat()
    crow = _find_or_create_counter(ws["id"], None, "minute", mstart)
    crow["exec_count"] = int(crow.get("exec_count") or 0) + 1
    crow["updated_at"] = _now()

    # authorize visibility: caller can only see its own workspace
    if id != ws.get("id"):
        # Persist counters + last_used_at, then return NOT_FOUND (not visible)
        _persist_auth_last_used(key_row)
        _save("usage_counters.json", counters)
        _save("api_keys.json", api_keys)
        return _err("NOT_FOUND", "Workspace not found")

    # found and visible
    _persist_auth_last_used(key_row)
    _save("usage_counters.json", counters)
    _save("api_keys.json", api_keys)

    # Return workspace as stored
    return {
        "workspace": ws,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        },
    }

def workspaces_update(
    api_key,
    id,
    name=None,
    status=None,
    default_timeout_ms=None,
    max_timeout_ms=None,
    max_command_length=None,
    allowed_cwd_roots=None,
    deny_command_regexes=None,
    allow_command_regexes=None,
    rate_limit_per_minute=None,
    daily_exec_limit=None,
    **_extra
):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0548000" if __import__("os").path.isdir("./environment_mix/0548000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc).isoformat()

    t0 = time.time()
    endpoint = "workspaces-update"

    # ---- validate required types
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    # ---- validate optional fields types/enums
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string")
        if status not in ("active", "suspended", "deleted"):
            return _err("VALIDATION_ERROR", "status must be one of: active, suspended, deleted")
    if default_timeout_ms is not None and (not isinstance(default_timeout_ms, int) or default_timeout_ms < 1):
        return _err("VALIDATION_ERROR", "default_timeout_ms must be an integer >= 1")
    if max_timeout_ms is not None and (not isinstance(max_timeout_ms, int) or max_timeout_ms < 1):
        return _err("VALIDATION_ERROR", "max_timeout_ms must be an integer >= 1")
    if max_command_length is not None and (not isinstance(max_command_length, int) or max_command_length < 1):
        return _err("VALIDATION_ERROR", "max_command_length must be an integer >= 1")
    if allowed_cwd_roots is not None:
        if not isinstance(allowed_cwd_roots, list) or any(not isinstance(x, str) for x in allowed_cwd_roots):
            return _err("VALIDATION_ERROR", "allowed_cwd_roots must be an array of strings")
    if deny_command_regexes is not None:
        if not isinstance(deny_command_regexes, list) or any(not isinstance(x, str) for x in deny_command_regexes):
            return _err("VALIDATION_ERROR", "deny_command_regexes must be an array of strings")
        # compile validation
        for pat in deny_command_regexes:
            try:
                re.compile(pat)
            except re.error:
                return _err("VALIDATION_ERROR", f"Invalid deny_command_regexes pattern: {pat}")
    if allow_command_regexes is not None:
        if not isinstance(allow_command_regexes, list) or any(not isinstance(x, str) for x in allow_command_regexes):
            return _err("VALIDATION_ERROR", "allow_command_regexes must be an array of strings")
        for pat in allow_command_regexes:
            try:
                re.compile(pat)
            except re.error:
                return _err("VALIDATION_ERROR", f"Invalid allow_command_regexes pattern: {pat}")
    if rate_limit_per_minute is not None and (not isinstance(rate_limit_per_minute, int) or rate_limit_per_minute < 1):
        # tool schema says minimum 0, but workspace constraint requires >=1
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be an integer >= 1")
    if daily_exec_limit is not None:
        if not isinstance(daily_exec_limit, int) or daily_exec_limit < 1:
            return _err("VALIDATION_ERROR", "daily_exec_limit must be null or an integer >= 1")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    counters = _load("usage_counters.json")

    # ---- authenticate (id OR key_prefix OR key_hash)
    key_row = None
    for k in api_keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key or k.get("key_hash") == api_key:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        return _err("UNAUTHORIZED", "API key is missing or invalid")

    # Must only allow updating own workspace (no separate roles in schema; enforce ownership)
    if key_row.get("workspace_id") != id:
        return _err("UNAUTHORIZED", "Not permitted to update this workspace")

    # Find workspace
    ws = None
    ws_idx = None
    for i, w in enumerate(workspaces):
        if w.get("id") == id:
            ws = w
            ws_idx = i
            break
    if not ws:
        return _err("NOT_FOUND", "Workspace not found")

    # ---- observable dynamics: count this call in usage_counters minute window (workspace aggregate)
    def _minute_start(dt):
        return dt.replace(second=0, microsecond=0)

    def _find_or_create_counter(workspace_id, api_key_id, window_type, window_start_iso):
        for r in counters:
            if (
                r.get("workspace_id") == workspace_id
                and r.get("api_key_id") == api_key_id
                and r.get("window_type") == window_type
                and r.get("window_start") == window_start_iso
            ):
                return r
        cid = f"uc_{int(time.time()*1000)}_{len(counters)+1}"
        row = {
            "id": cid,
            "workspace_id": workspace_id,
            "api_key_id": api_key_id,
            "window_type": window_type,
            "window_start": window_start_iso,
            "exec_count": 0,
            "rejected_count": 0,
            "timed_out_count": 0,
            "created_at": _now(),
            "updated_at": _now(),
        }
        counters.append(row)
        return row

    now_dt = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
    mstart = _minute_start(now_dt).isoformat()
    crow = _find_or_create_counter(ws["id"], None, "minute", mstart)
    crow["exec_count"] = int(crow.get("exec_count") or 0) + 1
    crow["updated_at"] = _now()

    # ---- apply updates to a copy, then validate constraints/uniques
    updated = dict(ws)

    # mutable fields
    if name is not None:
        updated["name"] = name.strip()
    if default_timeout_ms is not None:
        updated["default_timeout_ms"] = default_timeout_ms
    if max_timeout_ms is not None:
        updated["max_timeout_ms"] = max_timeout_ms
    if max_command_length is not None:
        updated["max_command_length"] = max_command_length
    if allowed_cwd_roots is not None:
        updated["allowed_cwd_roots"] = allowed_cwd_roots
    if deny_command_regexes is not None:
        updated["deny_command_regexes"] = deny_command_regexes
    if allow_command_regexes is not None:
        updated["allow_command_regexes"] = allow_command_regexes
    if rate_limit_per_minute is not None:
        updated["rate_limit_per_minute"] = rate_limit_per_minute
    if daily_exec_limit is not None or daily_exec_limit is None:
        # only change if explicitly provided (could be None to disable)
        if "daily_exec_limit" in locals():
            # but locals() always includes it; detect using parameter presence isn't possible here.
            # We treat daily_exec_limit argument value as intent if caller passed it; API surface doesn't tell.
            # Keep safe behavior: only set when not None OR explicitly None while other fields? can't detect.
            pass

    # detect whether caller intended to change daily_exec_limit:
    # if user passed daily_exec_limit=None explicitly, Python receives None indistinguishable from default.
    # Given tool schema includes null, we assume default is "not provided"; keep current unless non-None.
    if daily_exec_limit is not None:
        updated["daily_exec_limit"] = daily_exec_limit

    # status transition
    if status is not None:
        cur = ws.get("status")
        transitions = {"active": ["suspended", "deleted"], "suspended": ["active", "deleted"], "deleted": []}
        if cur != status:
            if status not in transitions.get(cur, []):
                # Persist counters + key usage, then return conflict/invalid transition
                key_row["last_used_at"] = _now()
                key_row["updated_at"] = _now()
                _save("usage_counters.json", counters)
                _save("api_keys.json", api_keys)
                return _err("CONFLICT", "Illegal workspace status transition", from_status=cur, to_status=status)
            updated["status"] = status

    # ---- constraint checks
    # default_timeout_ms >= 1 already checked
    if not isinstance(updated.get("default_timeout_ms"), int) or updated["default_timeout_ms"] < 1:
        return _err("VALIDATION_ERROR", "default_timeout_ms must be >= 1")
    if not isinstance(updated.get("max_timeout_ms"), int) or updated["max_timeout_ms"] < updated["default_timeout_ms"]:
        return _err("VALIDATION_ERROR", "max_timeout_ms must be >= default_timeout_ms")
    if updated["max_timeout_ms"] > 300000:
        return _err("VALIDATION_ERROR", "max_timeout_ms must be <= 300000")
    if not isinstance(updated.get("max_command_length"), int) or updated["max_command_length"] < 1:
        return _err("VALIDATION_ERROR", "max_command_length must be >= 1")
    if not isinstance(updated.get("rate_limit_per_minute"), int) or updated["rate_limit_per_minute"] < 1:
        return _err("VALIDATION_ERROR", "rate_limit_per_minute must be >= 1")
    if updated.get("daily_exec_limit") is not None:
        if not isinstance(updated["daily_exec_limit"], int) or updated["daily_exec_limit"] < 1:
            return _err("VALIDATION_ERROR", "daily_exec_limit must be null or >= 1")

    # ---- unique(name)
    if "name" in updated and isinstance(updated["name"], str):
        for w in workspaces:
            if w.get("id") != updated.get("id") and w.get("name") == updated.get("name"):
                key_row["last_used_at"] = _now()
                key_row["updated_at"] = _now()
                _save("usage_counters.json", counters)
                _save("api_keys.json", api_keys)
                return _err("CONFLICT", "Workspace name must be unique")

    # ---- if no changes, still must not report success without effect
    mutable_fields = [
        "name",
        "status",
        "default_timeout_ms",
        "max_timeout_ms",
        "max_command_length",
        "allowed_cwd_roots",
        "deny_command_regexes",
        "allow_command_regexes",
        "rate_limit_per_minute",
        "daily_exec_limit",
    ]
    changed = any(updated.get(f) != ws.get(f) for f in mutable_fields)
    if not changed:
        # Still log the call already; update last_used_at; but return NOT_FOUND? no.
        # Real APIs usually return the resource unchanged; however contract says no success without effect for mutations.
        key_row["last_used_at"] = _now()
        key_row["updated_at"] = _now()
        _save("usage_counters.json", counters)
        _save("api_keys.json", api_keys)
        return _err("CONFLICT", "No changes requested")

    # persist update
    updated["updated_at"] = _now()
    workspaces[ws_idx] = updated

    key_row["last_used_at"] = _now()
    key_row["updated_at"] = _now()

    _save("workspaces.json", workspaces)
    _save("usage_counters.json", counters)
    _save("api_keys.json", api_keys)

    return {
        "workspace": updated,
        "meta": {
            "latency_ms": int((time.time() - t0) * 1000),
            "timestamp": _now(),
        },
    }

def api_keys_list(api_key, workspace_id, status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0548000" if __import__("os").path.isdir("./environment_mix/0548000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, base64, hashlib

    t0 = time.time()
    now_iso = datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _rows(obj):
        if isinstance(obj, list): return obj
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list): return obj["rows"]
        return []

    ws_store = _load("workspaces.json")
    key_store = _load("api_keys.json")
    req_store = _load("request_logs.json")

    workspaces = _rows(ws_store)
    api_keys = _rows(key_store)
    request_logs = _rows(req_store)

    def _log(status_code, api_key_id=None, api_key_prefix=None, workspace_id=None, message=None):
        entry = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{os.getpid()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": "api_keys-list",
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_code,
            "api_key_id": api_key_id,
            "api_key_prefix": api_key_prefix,
            "workspace_id": workspace_id,
            "message": message,
        }
        request_logs.append(entry)

    # ---- validate ----
    if not isinstance(api_key, str) or not api_key.strip():
        _log("VALIDATION_ERROR", message="api_key must be a non-empty string")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        _log("VALIDATION_ERROR", message="workspace_id must be a non-empty string")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if status is not None and status not in ("active", "revoked"):
        _log("VALIDATION_ERROR", message="Invalid status")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "Invalid status", allowed=["active", "revoked"])
    if limit is None:
        limit = 50
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1 or limit > 200:
        _log("VALIDATION_ERROR", message="limit must be 1..200")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")
    if cursor is not None and not isinstance(cursor, str):
        _log("VALIDATION_ERROR", message="cursor must be a string")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # ---- authenticate ----
    cred = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            cred = k
            break
    if cred is None:
        _log("UNAUTHORIZED", message="API key missing or invalid")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key missing or invalid")
    if cred.get("status") != "active":
        _log("UNAUTHORIZED", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=cred.get("workspace_id"), message="API key revoked")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked")

    # ---- workspace existence ----
    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log("NOT_FOUND", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=workspace_id, message="workspace not found")
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Workspace not found")

    # ---- authorization (least-privilege): only list keys in caller's workspace ----
    if cred.get("workspace_id") != workspace_id:
        _log("UNAUTHORIZED", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=workspace_id, message="not permitted")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Not permitted")

    rows = [k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [k for k in rows if k.get("status") == status]

    # never return secret; key_hash is stored but is sensitive; omit it
    def _public(k):
        return {
            "id": k.get("id"),
            "workspace_id": k.get("workspace_id"),
            "name": k.get("name"),
            "key_prefix": k.get("key_prefix"),
            "status": k.get("status"),
            "last_used_at": k.get("last_used_at"),
            "created_at": k.get("created_at"),
            "updated_at": k.get("updated_at"),
        }

    rows.sort(key=lambda k: ((k.get("created_at") or ""), (k.get("id") or "")))

    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8", "replace")
            if raw.startswith("offset:"):
                offset = int(raw.split(":", 1)[1])
                if offset < 0:
                    offset = 0
        except Exception:
            offset = 0

    total = len(rows)
    page_rows = rows[offset: offset + limit]
    next_offset = offset + len(page_rows)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    _log("OK", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=workspace_id, message="listed")
    _save("request_logs.json", request_logs)
    return {
        "data": [_public(k) for k in page_rows],
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def api_keys_create(api_key, workspace_id, name, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0548000" if __import__("os").path.isdir("./environment_mix/0548000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    import time, hashlib, secrets

    t0 = time.time()

    def _rows(obj):
        if isinstance(obj, list): return obj
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list): return obj["rows"]
        return []

    ws_store = _load("workspaces.json")
    key_store = _load("api_keys.json")
    req_store = _load("request_logs.json")

    workspaces = _rows(ws_store)
    api_keys = _rows(key_store)
    request_logs = _rows(req_store)

    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _save_back(fname, original, rows):
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(fname, original)
        else:
            _save(fname, rows)

    def _log(status_code, api_key_id=None, api_key_prefix=None, workspace_id=None, message=None):
        entry = {
            "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{os.getpid()}".encode("utf-8")).hexdigest()[:24],
            "endpoint": "api_keys-create",
            "timestamp": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": status_code,
            "api_key_id": api_key_id,
            "api_key_prefix": api_key_prefix,
            "workspace_id": workspace_id,
            "message": message,
        }
        request_logs.append(entry)

    # ---- validate ----
    if not isinstance(api_key, str) or not api_key.strip():
        _log("VALIDATION_ERROR", message="api_key must be a non-empty string")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(workspace_id, str) or not workspace_id.strip():
        _log("VALIDATION_ERROR", message="workspace_id must be a non-empty string")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "workspace_id must be a non-empty string")
    if not isinstance(name, str) or not name.strip():
        _log("VALIDATION_ERROR", message="name must be a non-empty string")
        _save("request_logs.json", request_logs)
        return _err("VALIDATION_ERROR", "name must be a non-empty string")

    # ---- authenticate ----
    cred = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            cred = k
            break
    if cred is None:
        _log("UNAUTHORIZED", message="API key missing or invalid")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key missing or invalid")
    if cred.get("status") != "active":
        _log("UNAUTHORIZED", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=cred.get("workspace_id"), message="API key revoked")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "API key is revoked")

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
    if ws is None:
        _log("NOT_FOUND", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=workspace_id, message="workspace not found")
        _save("request_logs.json", request_logs)
        return _err("NOT_FOUND", "Workspace not found")

    # ---- authorization: only create keys in caller's workspace ----
    if cred.get("workspace_id") != workspace_id:
        _log("UNAUTHORIZED", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=workspace_id, message="not permitted")
        _save("request_logs.json", request_logs)
        return _err("UNAUTHORIZED", "Not permitted")

    # ---- constraints ----
    for k in api_keys:
        if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("name") == name:
            _log("CONFLICT", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=workspace_id, message="duplicate key name")
            _save("request_logs.json", request_logs)
            return _err("CONFLICT", "API key name must be unique within workspace")

    # ---- generate secret (one-time) ----
    # Store only a hash (no plaintext verification is ever needed); return secret to caller.
    secret = "rssk_" + secrets.token_urlsafe(24)
    key_hash = hashlib.sha256(secret.encode("utf-8")).hexdigest()
    key_prefix = secret[:10]
    if len(key_prefix) < 4 or len(key_prefix) > 32:
        key_prefix = secret[:12]

    # unique(key_hash), unique(key_prefix, workspace_id)
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("key_hash") == key_hash:
            # extremely unlikely, but must be conflict (idempotency not declared)
            _log("CONFLICT", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=workspace_id, message="key hash collision")
            _save("request_logs.json", request_logs)
            return _err("CONFLICT", "Key generation conflict, retry")
        if k.get("workspace_id") == workspace_id and k.get("key_prefix") == key_prefix:
            _log("CONFLICT", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=workspace_id, message="key prefix collision")
            _save("request_logs.json", request_logs)
            return _err("CONFLICT", "Key generation conflict, retry")

    new_id = "rss_key_" + hashlib.sha256(f"{time.time_ns()}:{os.getpid()}:{secrets.token_hex(8)}".encode("utf-8")).hexdigest()[:26]
    row = {
        "id": new_id,
        "workspace_id": workspace_id,
        "name": name,
        "key_hash": key_hash,
        "key_prefix": key_prefix,
        "status": "active",
        "last_used_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    api_keys.append(row)

    _log("OK", api_key_id=cred.get("id"), api_key_prefix=cred.get("key_prefix"), workspace_id=workspace_id, message="created")
    _save_back("api_keys.json", key_store, api_keys)
    _save("request_logs.json", request_logs)

    return {
        "secret": secret,
        "api_key": {
            "id": row["id"],
            "workspace_id": row["workspace_id"],
            "name": row["name"],
            "key_prefix": row["key_prefix"],
            "status": row["status"],
            "last_used_at": row["last_used_at"],
            "created_at": row["created_at"],
            "updated_at": row["updated_at"],
        },
    }

def api_keys_update(api_key, id, name=None, status=None, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0548000" if __import__("os").path.isdir("./environment_mix/0548000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    import time, hashlib

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc).isoformat()

    def _rows(obj):
        if isinstance(obj, list):
            return obj
        if isinstance(obj, dict) and isinstance(obj.get("rows"), list):
            return obj["rows"]
        return []

    def _save_back(fname, original, rows):
        if isinstance(original, dict) and isinstance(original.get("rows"), list):
            original["rows"] = rows
            _save(fname, original)
        else:
            _save(fname, rows)

    # Optional request log collection (not declared in schema, but may exist)
    req_store = _load("request_logs.json")
    request_logs = _rows(req_store)

    def _log(status_code, api_key_id=None, api_key_prefix=None, workspace_id=None, message=None):
        # Best-effort logging; never fail the call due to logging
        try:
            entry = {
                "id": "req_" + hashlib.sha256(f"{time.time_ns()}:{os.getpid()}".encode("utf-8")).hexdigest()[:24],
                "endpoint": "api_keys-update",
                "timestamp": _iso(now),
                "latency_ms": int((time.time() - t0) * 1000),
                "status": status_code,
                "api_key_id": api_key_id,
                "api_key_prefix": api_key_prefix,
                "workspace_id": workspace_id,
                "message": message,
            }
            request_logs.append(entry)
            _save_back("request_logs.json", req_store, request_logs)
        except Exception:
            pass

    # ---- validate inputs ----
    if not isinstance(api_key, str) or not api_key.strip():
        _log("VALIDATION_ERROR", message="api_key must be a non-empty string")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        _log("VALIDATION_ERROR", message="id must be a non-empty string")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        _log("VALIDATION_ERROR", message="name must be a non-empty string when provided")
        return _err("VALIDATION_ERROR", "name must be a non-empty string when provided")
    if status is not None:
        if not isinstance(status, str):
            _log("VALIDATION_ERROR", message="status must be a string when provided")
            return _err("VALIDATION_ERROR", "status must be a string when provided")
        if status not in ("active", "revoked"):
            _log("VALIDATION_ERROR", message="status must be one of: active, revoked")
            return _err("VALIDATION_ERROR", "status must be one of: active, revoked")

    # ---- load datastore ----
    keys_store = _load("api_keys.json")
    keys = _rows(keys_store)
    ws_store = _load("workspaces.json")
    workspaces = _rows(ws_store)

    def _find_key_by_credential(val):
        # IMPORTANT: stored plaintext secret is NOT available; authenticate by id OR by key_prefix (client-visible)
        # We choose an *active* key for authentication.
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if val == k.get("id") or val == k.get("key_prefix"):
                return k
        # As a last attempt, allow referencing any key by id for auth if it's active already checked above.
        return None

    auth_key = _find_key_by_credential(api_key.strip())
    if not auth_key:
        _log("UNAUTHORIZED", message="invalid or inactive api_key")
        return _err("UNAUTHORIZED", "Invalid or inactive api_key")

    auth_ws_id = auth_key.get("workspace_id")
    auth_ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == auth_ws_id), None)
    if not auth_ws:
        _log("UNAUTHORIZED", api_key_id=auth_key.get("id"), api_key_prefix=auth_key.get("key_prefix"), workspace_id=auth_ws_id, message="api_key workspace not found")
        return _err("UNAUTHORIZED", "Authenticated workspace not found")

    # ---- locate target key (must be visible within authenticated workspace) ----
    target = next((k for k in keys if isinstance(k, dict) and k.get("id") == id.strip() and k.get("workspace_id") == auth_ws_id), None)
    if not target:
        _log("NOT_FOUND", api_key_id=auth_key.get("id"), api_key_prefix=auth_key.get("key_prefix"), workspace_id=auth_ws_id, message="API key not found in workspace")
        return _err("NOT_FOUND", "API key not found")

    # ---- enforce constraints & lifecycle transitions ----
    mutated = False
    old_status = target.get("status")

    if name is not None:
        new_name = name.strip()
        # unique(workspace_id, name)
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("workspace_id") == auth_ws_id and k.get("id") != target.get("id") and k.get("name") == new_name:
                _log("CONFLICT", api_key_id=auth_key.get("id"), api_key_prefix=auth_key.get("key_prefix"), workspace_id=auth_ws_id, message="unique(workspace_id, name) violated")
                return _err("CONFLICT", "Key name must be unique within the workspace")
        if target.get("name") != new_name:
            target["name"] = new_name
            mutated = True

    if status is not None:
        if old_status not in ("active", "revoked"):
            _log("VALIDATION_ERROR", api_key_id=auth_key.get("id"), api_key_prefix=auth_key.get("key_prefix"), workspace_id=auth_ws_id, message="stored key has invalid status")
            return _err("VALIDATION_ERROR", "Stored key has invalid status")
        if status == old_status:
            # idempotent update for status
            pass
        else:
            # lifecycle: active -> revoked only
            if old_status == "active" and status == "revoked":
                target["status"] = "revoked"
                mutated = True
            else:
                _log("CONFLICT", api_key_id=auth_key.get("id"), api_key_prefix=auth_key.get("key_prefix"), workspace_id=auth_ws_id, message=f"illegal transition {old_status}->{status}")
                return _err("CONFLICT", f"Illegal status transition {old_status}→{status}")

    if not mutated:
        # No success without effect for mutations; if caller provided no changes, treat as validation error.
        _log("VALIDATION_ERROR", api_key_id=auth_key.get("id"), api_key_prefix=auth_key.get("key_prefix"), workspace_id=auth_ws_id, message="no fields to update")
        return _err("VALIDATION_ERROR", "No changes requested")

    # ---- persist & audit ----
    target["updated_at"] = _iso(now)

    # If the authenticated key is the one being used, update last_used_at on successful auth
    auth_key_row = next((k for k in keys if isinstance(k, dict) and k.get("id") == auth_key.get("id")), None)
    if auth_key_row is not None:
        auth_key_row["last_used_at"] = _iso(now)
        auth_key_row["updated_at"] = _iso(now)

    _save_back("api_keys.json", keys_store, keys)

    # ---- response (never include secret) ----
    resp = {k: v for k, v in target.items() if k != "key_hash"}
    _log("OK", api_key_id=auth_key.get("id"), api_key_prefix=auth_key.get("key_prefix"), workspace_id=auth_ws_id, message="updated")
    return {"data": resp}
